import json

a = 17
b = 23
# Builtin multiplication
prod1 = a * b
# Alternate algorithm: repeated addition
prod2 = 0
for _ in range(b):
    prod2 += a

mods = [2, 3, 9, 11]
res = {}
expected = {}
for m in mods:
    res[m] = {"a": a % m, "b": b % m, "prod1": prod1 % m, "prod2": prod2 % m}
    expected[m] = ((a % m) * (b % m)) % m

checks = {}
all_ok = True
for m in mods:
    ok_prod = (res[m]["prod1"] == expected[m]) and (res[m]["prod2"] == expected[m])
    checks[str(m)] = ok_prod
    if not ok_prod:
        all_ok = False

verified = (prod1 == prod2) and all_ok

out = {
    "product_builtin": prod1,
    "product_alt": prod2,
    "residues": res,
    "expected_residues": expected,
    "checks": checks,
    "verified": verified
}
print(json.dumps(out))
